import React, { ReactElement, useCallback, useEffect, useMemo, useState } from "react";
import { MatrixEvent } from "matrix-js-sdk/src/models/event";
import { logger } from "matrix-js-sdk/src/logger";
import { Room } from "matrix-js-sdk/src/models/room";
import { RoomMember } from "matrix-js-sdk/src/models/room-member";

import { MatrixClientPeg } from "../MatrixClientPeg";
import dis from "../dispatcher/dispatcher";
import { Action } from "../dispatcher/actions";
import { ButtonEvent } from "../components/views/elements/AccessibleButton";
import MemberAvatar from "../components/views/avatars/MemberAvatar";
import RoomAvatar from "../components/views/avatars/RoomAvatar";
import { getPrimaryPermalinkEntity } from "../utils/permalinks/Permalinks";

export enum PillType {
    UserMention = "TYPE_USER_MENTION",
    RoomMention = "TYPE_ROOM_MENTION",
    AtRoomMention = "TYPE_AT_ROOM_MENTION",
}

export interface UsePermalinkArgs {
    url?: string;
    type?: PillType;
    room?: Room;
}

export interface UsePermalinkResult {
    avatar: ReactElement | null;
    text: string | null;
    onClick: ((e: ButtonEvent) => void) | null;
    resourceId: string | null;
    type: PillType | "space" | null;
}

interface ProfileInfo {
    userId: string;
    displayName?: string;
    avatarUrl?: string;
}

const EMPTY_RESULT: UsePermalinkResult = {
    avatar: null,
    text: null,
    onClick: null,
    resourceId: null,
    type: null,
};

function getTypeFromEntity(entity: string | null): PillType | null {
    switch (entity?.[0]) {
        case "@":
            return PillType.UserMention;
        case "!":
        case "#":
            return PillType.RoomMention;
        default:
            return null;
    }
}

function resolveRoom(resourceId: string, type: PillType, room: Room | undefined): Room | null {
    if (type === PillType.AtRoomMention) return room ?? null;

    const client = MatrixClientPeg.get();
    if (resourceId.startsWith("#")) {
        return (
            client
                .getRooms()
                .find(
                    (candidate) =>
                        candidate.getCanonicalAlias() === resourceId || candidate.getAltAliases().includes(resourceId),
                ) ?? null
        );
    }

    return client.getRoom(resourceId) ?? null;
}

export function usePermalink({ url, type: requestedType, room }: UsePermalinkArgs): UsePermalinkResult {
    const entity = url ? getPrimaryPermalinkEntity(url) : null;
    const resolvedType = requestedType ?? getTypeFromEntity(entity);

    // @room is only meaningful when explicitly requested and scoped to a room.
    const resourceId =
        resolvedType === PillType.AtRoomMention
            ? room?.roomId ?? null
            : entity && getTypeFromEntity(entity) === resolvedType
            ? entity
            : null;

    const roomEntity =
        resourceId && resolvedType && resolvedType !== PillType.UserMention
            ? resolveRoom(resourceId, resolvedType, room)
            : null;

    const userId = resolvedType === PillType.UserMention ? resourceId : null;
    const localMember = userId && room ? room.getMember(userId) : null;
    const [profile, setProfile] = useState<ProfileInfo | null>(null);

    useEffect(() => {
        setProfile(null);
        if (!userId || localMember) return;

        let isCurrent = true;
        MatrixClientPeg.get()
            .getProfileInfo(userId)
            .then((response) => {
                if (isCurrent) {
                    setProfile({
                        userId,
                        displayName: response.displayname,
                        avatarUrl: response.avatar_url,
                    });
                }
            })
            .catch((error) => {
                logger.error("Could not retrieve profile data for " + userId + ":", error);
            });

        return () => {
            isCurrent = false;
        };
    }, [userId, localMember]);

    const member = useMemo(() => {
        if (!userId) return null;
        if (localMember) return localMember;

        const resolvedMember = new RoomMember(null, userId);
        if (profile?.userId === userId) {
            resolvedMember.name = profile.displayName;
            resolvedMember.rawDisplayName = profile.displayName || userId;
            if (profile.avatarUrl) {
                resolvedMember.events.member = {
                    getContent: () => ({ avatar_url: profile.avatarUrl }),
                    getDirectionalContent: function () {
                        return this.getContent();
                    },
                } as MatrixEvent;
            }
        }
        return resolvedMember;
    }, [localMember, profile, userId]);

    const onClick = useCallback(
        (event: ButtonEvent): void => {
            if (!member) return;
            event.preventDefault();
            dis.dispatch({
                action: Action.ViewUser,
                member,
            });
        },
        [member],
    );

    if (!resolvedType || !resourceId) return EMPTY_RESULT;

    if (resolvedType === PillType.AtRoomMention) {
        return {
            avatar: room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
            text: "@room",
            onClick: null,
            resourceId,
            type: PillType.AtRoomMention,
        };
    }

    if (resolvedType === PillType.UserMention) {
        if (!member) return EMPTY_RESULT;
        return {
            avatar: <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />,
            text: member.rawDisplayName || member.name || userId,
            onClick,
            resourceId,
            type: PillType.UserMention,
        };
    }

    const isSpace = roomEntity?.isSpaceRoom() ?? false;
    return {
        avatar: roomEntity ? <RoomAvatar room={roomEntity} width={16} height={16} aria-hidden="true" /> : null,
        text: roomEntity?.name || resourceId,
        onClick: null,
        resourceId,
        type: isSpace ? "space" : PillType.RoomMention,
    };
}
