import React, { useState } from "react";
import classNames from "classnames";
import { Room } from "matrix-js-sdk/src/models/room";

import { MatrixClientPeg } from "../../../MatrixClientPeg";
import MatrixClientContext from "../../../contexts/MatrixClientContext";
import { usePermalink, PillType } from "../../../hooks/usePermalink";
import Tooltip, { Alignment } from "./Tooltip";

export { PillType };

export interface PillProps {
    /** The type of this Pill. If url is given, this is auto-detected. */
    type?: PillType;
    /** The URL to pillify. */
    url?: string;
    /** Whether the pill is being rendered in a message. */
    inMessage?: boolean;
    /** The room in which this pill is being rendered. */
    room?: Room;
    /** Whether to include an avatar in the pill. */
    shouldShowPillAvatar?: boolean;
}

export const pillRoomNotifPos = (text: string): number => text.indexOf("@room");

export const pillRoomNotifLen = (): number => "@room".length;

export function Pill({
    type: requestedType,
    url,
    inMessage,
    room,
    shouldShowPillAvatar,
}: PillProps): JSX.Element | null {
    const { avatar, text, onClick, resourceId, type } = usePermalink({ url, type: requestedType, room });
    const [hovering, setHovering] = useState(false);

    if (!type || text === null) return null;

    const classes = classNames("mx_Pill", {
        mx_UserPill: type === PillType.UserMention,
        mx_UserPill_me: type === PillType.UserMention && resourceId === MatrixClientPeg.get().getUserId(),
        mx_RoomPill: type === PillType.RoomMention || type === "space",
        mx_SpacePill: type === "space",
        mx_AtRoomPill: type === PillType.AtRoomMention,
    });
    const tip = hovering && resourceId ? <Tooltip label={resourceId} alignment={Alignment.Right} /> : null;
    const content = (
        <>
            {shouldShowPillAvatar === true ? avatar : null}
            <span className="mx_Pill_linkText">{text}</span>
            {tip}
        </>
    );
    const handleMouseEnter = (): void => setHovering(true);
    const handleMouseLeave = (): void => setHovering(false);

    return (
        <bdi>
            <MatrixClientContext.Provider value={MatrixClientPeg.get()}>
                {inMessage && url ? (
                    <a
                        className={classes}
                        href={url}
                        onClick={type === PillType.UserMention ? onClick : undefined}
                        onMouseEnter={handleMouseEnter}
                        onMouseLeave={handleMouseLeave}
                    >
                        {content}
                    </a>
                ) : (
                    <span className={classes} onMouseEnter={handleMouseEnter} onMouseLeave={handleMouseLeave}>
                        {content}
                    </span>
                )}
            </MatrixClientContext.Provider>
        </bdi>
    );
}

