 20	import { Room } from "matrix-js-sdk/src/models/room";
 21	import { RoomMember } from "matrix-js-sdk/src/models/room-member";
 22	
 23	import { MatrixClientPeg } from "../MatrixClientPeg";
 24	import dis from "../dispatcher/dispatcher";
 25	import { Action } from "../dispatcher/actions";
 26	import { ButtonEvent } from "../components/views/elements/AccessibleButton";
 27	import MemberAvatar from "../components/views/avatars/MemberAvatar";
 28	import RoomAvatar from "../components/views/avatars/RoomAvatar";
 29	import { getPrimaryPermalinkEntity } from "../utils/permalinks/Permalinks";
 30	
 31	export enum PillType {
 32	    UserMention = "TYPE_USER_MENTION",
 33	    RoomMention = "TYPE_ROOM_MENTION",
 34	    AtRoomMention = "TYPE_AT_ROOM_MENTION",
 35	}
 36	
 37	export interface UsePermalinkArgs {
 38	    url?: string;
 39	    type?: PillType;
 40	    room?: Room;
 41	}
 42	
 43	export interface UsePermalinkResult {
 44	    avatar: ReactElement | null;
 45	    text: string | null;
 46	    onClick: ((e: ButtonEvent) => void) | null;
 47	    resourceId: string | null;
 48	    type: PillType | "space" | null;
 49	}
 50	
 51	interface ProfileInfo {
 52	    userId: string;
 53	    displayName?: string;
 54	    avatarUrl?: string;
 55	}
 56	
 57	const EMPTY_RESULT: UsePermalinkResult = {
 58	    avatar: null,
 59	    text: null,
 60	    onClick: null,
 61	    resourceId: null,
 62	    type: null,
 63	};
 64	
 65	function getTypeFromEntity(entity: string | null): PillType | null {
 66	    switch (entity?.[0]) {
 67	        case "@":
 68	            return PillType.UserMention;
 69	        case "!":
 70	        case "#":
 71	            return PillType.RoomMention;
 72	        default:
 73	            return null;
 74	    }
 75	}
 76	
 77	function resolveRoom(resourceId: string, type: PillType, room: Room | undefined): Room | null {
 78	    if (type === PillType.AtRoomMention) return room ?? null;
 79	
 80	    const client = MatrixClientPeg.get();
 81	    if (resourceId.startsWith("#")) {
 82	        return (
 83	            client
 84	                .getRooms()
 85	                .find(
 86	                    (candidate) =>
 87	                        candidate.getCanonicalAlias() === resourceId || candidate.getAltAliases().includes(resourceId),
 88	                ) ?? null
 89	        );
 90	    }
 91	
 92	    return client.getRoom(resourceId) ?? null;
 93	}
 94	
 95	export function usePermalink({ url, type: requestedType, room }: UsePermalinkArgs): UsePermalinkResult {
 96	    const entity = url ? getPrimaryPermalinkEntity(url) : null;
 97	    const resolvedType = requestedType ?? getTypeFromEntity(entity);
 98	
 99	    // @room is only meaningful when explicitly requested and scoped to a room.
100	    const resourceId =
101	        resolvedType === PillType.AtRoomMention
102	            ? room?.roomId ?? null
103	            : entity && getTypeFromEntity(entity) === resolvedType
104	            ? entity
105	            : null;
106	
107	    const roomEntity =
108	        resourceId && resolvedType && resolvedType !== PillType.UserMention
109	            ? resolveRoom(resourceId, resolvedType, room)
110	            : null;
111	
112	    const userId = resolvedType === PillType.UserMention ? resourceId : null;
113	    const localMember = userId && room ? room.getMember(userId) : null;
114	    const [profile, setProfile] = useState<ProfileInfo | null>(null);
115	
116	    useEffect(() => {
117	        setProfile(null);
118	        if (!userId || localMember) return;
119	
120	        let isCurrent = true;
121	        MatrixClientPeg.get()
122	            .getProfileInfo(userId)
123	            .then((response) => {
124	                if (isCurrent) {
125	                    setProfile({
126	                        userId,
127	                        displayName: response.displayname,
128	                        avatarUrl: response.avatar_url,
129	                    });
130	                }
131	            })
132	            .catch((error) => {
133	                logger.error("Could not retrieve profile data for " + userId + ":", error);
134	            });
135	
136	        return () => {
137	            isCurrent = false;
138	        };
139	    }, [userId, localMember]);
140	
141	    const member = useMemo(() => {
142	        if (!userId) return null;
143	        if (localMember) return localMember;
144	
145	        const resolvedMember = new RoomMember(null, userId);
146	        if (profile?.userId === userId) {
147	            resolvedMember.name = profile.displayName;
148	            resolvedMember.rawDisplayName = profile.displayName || userId;
149	            if (profile.avatarUrl) {
150	                resolvedMember.events.member = {
151	                    getContent: () => ({ avatar_url: profile.avatarUrl }),
152	                    getDirectionalContent: function () {
153	                        return this.getContent();
154	                    },
155	                } as MatrixEvent;
156	            }
157	        }
158	        return resolvedMember;
159	    }, [localMember, profile, userId]);
160	
161	    const onClick = useCallback(
162	        (event: ButtonEvent): void => {
163	            if (!member) return;
164	            event.preventDefault();
165	            dis.dispatch({
166	                action: Action.ViewUser,
167	                member,
168	            });
169	        },
170	        [member],
171	    );
172	
173	    if (!resolvedType || !resourceId) return EMPTY_RESULT;
174	
175	    if (resolvedType === PillType.AtRoomMention) {
176	        return {
177	            avatar: room ? <RoomAvatar room={room} width={16} height={16} aria-hidden="true" /> : null,
178	            text: "@room",
179	            onClick: null,
180	            resourceId,
181	            type: PillType.AtRoomMention,
182	        };
183	    }
184	
185	    if (resolvedType === PillType.UserMention) {
186	        if (!member) return EMPTY_RESULT;
187	        return {
188	            avatar: <MemberAvatar member={member} width={16} height={16} aria-hidden="true" hideTitle />,
189	            text: member.rawDisplayName || member.name || userId,
190	            onClick,
191	            resourceId,
192	            type: PillType.UserMention,
193	        };
194	    }
195	
196	    const isSpace = roomEntity?.isSpaceRoom() ?? false;
197	    return {
198	        avatar: roomEntity ? <RoomAvatar room={roomEntity} width={16} height={16} aria-hidden="true" /> : null,
199	        text: roomEntity?.name || resourceId,
200	        onClick: null,
201	        resourceId,
202	        type: isSpace ? "space" : PillType.RoomMention,
203	    };
204	}
